        runs = []
        c = 3
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] != 0:
                c += 1
            runs.append((c-a, a, c))
        if not runs:
            continue
        _, a, b = max(runs)
        seq = grid[r][a:b]
        period = len(seq)
        for p in range(1, len(seq)+1):
